// Holt das Binary-PDF als Buffer und gibt es als reinen Base64-String weiter.
// Funktioniert mit n8n's binary storage modes 'default' (in-memory base64),
// 'filesystem' (file-ref), und 's3' (URL).
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const b64 = buffer.toString('base64');
const bin = $input.first().binary.data;
return [{ json: { pdf_base64: b64, mime_type: bin.mimeType || 'application/pdf' } }];

