// Parse Claude's JSON-Antwort, splitte in Antrag-Payload + Belegpositionen.
// extrahiert_anzeige enthält ALLE Werte (für UE0-Status-Vorschau);
// extrahiert (ohne Kosten) wird in apl2.antraege geinserted (Mig 016).
const input = $input.first().json;
const content = input.content?.[0]?.text;
if (!content) throw new Error('Claude lieferte keinen Text-Content: ' + JSON.stringify(input));
let extr;
try {
  const cleaned = content.trim().replace(/^```json\n?/, '').replace(/\n?```$/, '');
  extr = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Claude-Antwort ist kein JSON: ' + content.slice(0, 500));
}
// Backup Kostenfelder für UE0-Status-Anzeige
const betriebskosten = extr.betriebskosten_vorjahr_euro;
const personalkosten = extr.personalkosten_vorjahr_euro;
const miete_monat    = extr.monatliche_miete_euro;
// Snapshot ALLER Werte für die UE0-Status-Vorschau (mit Kosten!)
const extrahiert_anzeige = { ...extr };
// Aus dem antraege-INSERT-Payload entfernen (Mig 016: Kosten in belegposition)
delete extr.betriebskosten_vorjahr_euro;
delete extr.personalkosten_vorjahr_euro;
delete extr.monatliche_miete_euro;
extr.submitted_language = 'de';
extr.antragsdatum = extr.antragsdatum || new Date().toISOString().slice(0, 10);
extr.status = 'eingegangen';
if (!extr.foerderbereich) extr.foerderbereich = 'begegnungszentren';
// extrahiert_anzeige bekommt die Status-Felder ebenfalls
extrahiert_anzeige.submitted_language = 'de';
extrahiert_anzeige.antragsdatum = extr.antragsdatum;
extrahiert_anzeige.foerderbereich = extr.foerderbereich;
const belegpositionen = [];
if (typeof betriebskosten === 'number' && betriebskosten > 0) {
  belegpositionen.push({ belegtyp: 'betriebskosten', bezeichnung: 'Nachgewiesene Höhe der Betriebskosten des Vorjahres (aus OCR)', betrag_euro: betriebskosten });
}
if (typeof personalkosten === 'number' && personalkosten > 0) {
  belegpositionen.push({ belegtyp: 'personalkosten', bezeichnung: 'Nachgewiesene Höhe der Personalkosten des Vorjahres (aus OCR)', betrag_euro: personalkosten });
}
if (typeof miete_monat === 'number' && miete_monat > 0) {
  belegpositionen.push({ belegtyp: 'miete', bezeichnung: 'Mietzahlungen — Jahressumme (aus PDF-Monatsangabe: ' + miete_monat + ' €/Monat × 12, gem. „Monatliche Mietzahlungen in Höhe von …, Kopie Mietvertrag")', betrag_euro: miete_monat * 12 });
}
return [{ json: { extrahiert: extr, extrahiert_anzeige, belegpositionen, einreichung_id: $('Webhook Trigger (Supabase NOTIFY)').first().json.body.einreichung_id } }];

// Annotiert die Belegpositionen mit der antrag_id aus dem vorhergehenden
// INSERT. PostgREST liefert mit Prefer=return=representation ggf. ein Array
// oder ein Object — beides abfangen.
const raw = $input.first().json;
const inserted = Array.isArray(raw) ? raw[0] : raw;
const antragId = inserted && inserted.id;
if (!antragId) {
  throw new Error('INSERT apl2.antraege lieferte keine ID zurück: ' + JSON.stringify(raw));
}
const beleg = $('Parse JSON + Defaults + Belegpositionen-Split').first().json.belegpositionen || [];
if (beleg.length === 0) {
  return [{ json: { antrag_id: antragId, belegpositionen: [], _skip_belegposition: true } }];
}
return beleg.map(b => ({
  json: { ...b, antrag_id: antragId, _skip_belegposition: false }
}));

